-- VOIDRIFT: apply in Supabase SQL Editor, once. All submissions are written through the authenticated Edge Function.
create extension if not exists pgcrypto;

create table if not exists public.game_prompts (
  tag text primary key, label text not null, prompt text not null,
  description text not null, hint text not null, is_daily boolean not null default false
);
create table if not exists public.game_answers (
  prompt_tag text not null references public.game_prompts(tag) on delete cascade,
  normalized text not null, display_answer text not null,
  editorial_score integer not null check (editorial_score in (10,25,45,65,85,100)),
  primary key(prompt_tag,normalized)
);
create table if not exists public.player_profiles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  display_name text not null check(length(display_name) between 2 and 24),
  created_at timestamptz not null default now()
);
create table if not exists public.game_runs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  day date not null,
  mode text not null default 'daily' check(mode in ('daily','practice')),
  genre text not null default 'mixed',
  mission_tags text[] not null,
  progress integer not null default 0 check(progress between 0 and 10),
  total_score integer not null default 0 check(total_score between 0 and 1000),
  destinations integer not null default 0 check(destinations between 0 and 10),
  finished_at timestamptz,
  question_started_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);
create unique index if not exists game_runs_one_daily_per_user_day on public.game_runs(user_id,day) where mode='daily';
create index if not exists game_runs_leaderboard on public.game_runs(day, total_score desc) where mode='daily' and finished_at is not null;

create table if not exists public.game_submissions (
  id bigint generated always as identity primary key,
  run_id uuid not null references public.game_runs(id) on delete cascade,
  prompt_index integer not null check(prompt_index between 0 and 9),
  prompt_tag text not null references public.game_prompts(tag),
  answer_text text not null,
  canonical_answer text,
  points integer not null check(points in (0,10,25,45,65,85,100)),
  verdict text not null check(verdict in ('bank','ai','timeout','pass','invalid')),
  submitted_at timestamptz not null default now(),
  unique(run_id,prompt_index)
);
create index if not exists game_submissions_analytics on public.game_submissions(prompt_tag,canonical_answer,submitted_at);

create table if not exists public.game_answer_reports (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  prompt_tag text not null references public.game_prompts(tag),
  answer_text text not null,
  status text not null default 'pending' check(status in ('pending','approved','rejected')),
  created_at timestamptz not null default now(),
  unique(user_id,prompt_tag,answer_text)
);

create table if not exists public.practice_history (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  client_run_id text not null,
  genre text not null,
  score integer not null check(score between 0 and 1000),
  destinations integer not null check(destinations between 0 and 10),
  created_at timestamptz not null default now(),
  unique(user_id,client_run_id)
);

-- No client writes: only the Edge Function's service-role client can change these rows.
alter table public.game_prompts enable row level security;
alter table public.game_answers enable row level security;
alter table public.player_profiles enable row level security;
alter table public.game_runs enable row level security;
alter table public.game_submissions enable row level security;
alter table public.game_answer_reports enable row level security;
alter table public.practice_history enable row level security;
revoke all on public.game_prompts,public.game_answers,public.player_profiles,public.game_runs,public.game_submissions,public.game_answer_reports,public.practice_history from anon,authenticated;
revoke all on sequence public.game_submissions_id_seq, public.game_answer_reports_id_seq from anon,authenticated;
-- Edge Function uses its secret server-side key to access these tables.


-- Curated catalog: editable and expandable by the owner.


-- Calculates rarity from PREVIOUS daily flights so a day's scoring is fair to early and late players.
create or replace function public.voidrift_rarity_stats(p_prompt text,p_answer text,p_before date)
returns table(total bigint,matches bigint) language sql stable security invoker set search_path=public
as $$
 select count(*)::bigint, count(*) filter(where s.canonical_answer=p_answer)::bigint
 from public.game_submissions s join public.game_runs r on r.id=s.run_id
 where s.prompt_tag=p_prompt and s.points>0 and s.canonical_answer is not null
   and r.mode='daily' and r.day<p_before;
$$;
revoke all on function public.voidrift_rarity_stats(text,text,date) from public,anon,authenticated;
grant execute on function public.voidrift_rarity_stats(text,text,date) to service_role;


-- Score and progress commit as a single transaction. The function runs only
-- as the service role; client-provided scores never go directly to this RPC.
create or replace function public.voidrift_commit_answer(
  p_run_id uuid,
  p_prompt_index integer,
  p_prompt_tag text,
  p_answer text,
  p_canonical text,
  p_points integer,
  p_verdict text,
  p_correct boolean
)
returns table(next_index integer,next_score integer,next_destinations integer,is_finished boolean)
language plpgsql security invoker set search_path = public
as $$
declare
  current_run public.game_runs%rowtype;
  new_progress integer;
begin
  select * into current_run from public.game_runs where id = p_run_id for update;
  if not found then raise exception 'Run not found'; end if;
  if current_run.finished_at is not null or current_run.progress <> p_prompt_index
     or p_prompt_index < 0 or p_prompt_index > 9
     or current_run.mission_tags[p_prompt_index+1] is distinct from p_prompt_tag
  then
    raise exception 'Run out of sync';
  end if;
  if p_points not in (0,10,25,45,65,85,100)
    or p_verdict not in ('bank','ai','timeout','pass','invalid')
    or (p_correct is distinct from (p_points > 0))
  then
    raise exception 'Invalid answer result';
  end if;
  values (p_run_id,p_prompt_index,p_prompt_tag,left(p_answer,70),p_canonical,p_points,p_verdict);
  new_progress := p_prompt_index + 1;
  update public.game_runs
    set progress = new_progress,
        total_score = current_run.total_score + p_points,
        destinations = current_run.destinations + case when p_correct then 1 else 0 end,
        question_started_at = now() + interval '2.9 seconds',
        finished_at = case when new_progress = 10 then now() else null end
    where id = p_run_id;
  return query select new_progress,
    (current_run.total_score + p_points),
    (current_run.destinations + case when p_correct then 1 else 0 end),
    (new_progress = 10);
end;
$$;
revoke all on function public.voidrift_commit_answer(uuid,integer,text,text,text,integer,text,boolean) from public,anon,authenticated;
grant execute on function public.voidrift_commit_answer(uuid,integer,text,text,text,integer,text,boolean) to service_role;


-- Limit paid / expensive AI verification requests per user and daily prompt.
create table if not exists public.game_verification_attempts (
 user_id uuid not null references auth.users(id) on delete cascade,
 day date not null,
 prompt_index integer not null check (prompt_index between 0 and 9),
 attempts integer not null default 0 check (attempts >= 0),
 primary key (user_id,day,prompt_index)
);
alter table public.game_verification_attempts enable row level security;
revoke all on public.game_verification_attempts from anon,authenticated;

create or replace function public.voidrift_consume_verification(
 p_user_id uuid,p_day date,p_prompt_index integer
) returns integer language plpgsql security invoker set search_path=public as $$
declare n integer;
begin
 values (p_user_id,p_day,p_prompt_index,1)
 on conflict(user_id,day,prompt_index)
 do update set attempts=public.game_verification_attempts.attempts+1
 returning attempts into n;
 return n;
end;
$$;
revoke all on function public.voidrift_consume_verification(uuid,date,integer) from public,anon,authenticated;
grant execute on function public.voidrift_consume_verification(uuid,date,integer) to service_role;
